<?php require 'config.php';require_login();$u=user();layout_start('Dashboard');
if($u['role']==='volunteer'){
$s=db()->prepare("SELECT COUNT(*) total, SUM(CASE WHEN status='Diterima' THEN 1 ELSE 0 END) diterima FROM registrations WHERE volunteer_id=?");$s->execute([$u['user_id']]);$stats=$s->fetch();
$s=db()->prepare("SELECT h.*, (SELECT COUNT(*) FROM certificates c JOIN registrations r ON r.pendaftaran_id=c.pendaftaran_id WHERE r.volunteer_id=h.volunteer_id) cert FROM contribution_history h WHERE volunteer_id=?");$s->execute([$u['user_id']]);$h=$s->fetch();
$s=db()->prepare("SELECT r.status,e.nama_kegiatan,e.tanggal,e.lokasi,e.kegiatan_id FROM registrations r JOIN events e ON e.kegiatan_id=r.kegiatan_id WHERE r.volunteer_id=? ORDER BY r.tanggal_daftar DESC LIMIT 8");$s->execute([$u['user_id']]);$rows=$s->fetchAll();?>
<div class="page-heading"><span class="eyebrow">RUANG VOLUNTEER</span><h1>Halo, <?=e($u['nama'])?> 👋</h1><p class="muted">Pantau aktivitas dan kontribusi sosialmu.</p></div><div class="stats"><div class="stat"><small>Total pendaftaran</small><b><?=$stats['total']??0?></b><span>kegiatan diikuti</span></div><div class="stat"><small>Kegiatan diterima</small><b><?=$stats['diterima']??0?></b><span>siap diikuti</span></div><div class="stat"><small>Total kontribusi</small><b><?=e($h['total_jam']??0)?> <i>jam</i></b><span><?=e($h['jumlah_kegiatan']??0)?> kegiatan selesai</span></div><div class="stat"><small>Sertifikat</small><b><?=e($h['cert']??0)?></b><span>sertifikat tersedia</span></div></div><div class="section-head"><h2>Pendaftaran terbaru</h2><a href="index.php">Cari kegiatan →</a></div><?php if(!$rows):?><div class="empty"><h3>Belum ada pendaftaran</h3><p>Temukan kegiatan pertamamu dan mulai berkontribusi.</p><a class="btn btn-primary" href="index.php">Jelajahi kegiatan</a></div><?php else:?><div class="table-wrap"><table><tr><th>Kegiatan</th><th>Tanggal</th><th>Lokasi</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><a href="event.php?id=<?=$r['kegiatan_id']?>"><?=e($r['nama_kegiatan'])?></a></td><td><?=date('d M Y',strtotime($r['tanggal']))?></td><td><?=e($r['lokasi'])?></td><td><?=badge($r['status'])?></td></tr><?php endforeach;?></table></div><?php endif;
}elseif($u['role']==='organisasi'){
$s=db()->prepare("SELECT COUNT(*) n FROM events WHERE organisasi_id=?");$s->execute([$u['user_id']]);$n=$s->fetchColumn();
$s=db()->prepare("SELECT e.*,COUNT(r.pendaftaran_id) pendaftar FROM events e LEFT JOIN registrations r ON r.kegiatan_id=e.kegiatan_id WHERE e.organisasi_id=? GROUP BY e.kegiatan_id ORDER BY e.created_at DESC");$s->execute([$u['user_id']]);$rows=$s->fetchAll();
$s=db()->prepare("SELECT * FROM organizations WHERE user_id=?");$s->execute([$u['user_id']]);$org=$s->fetch();?>
<div class="page-heading"><span class="eyebrow">DASHBOARD ORGANISASI</span><h1><?=e($org['nama_organisasi'])?></h1><p class="muted">Kelola kegiatan dan pendaftar volunteer.</p><?php if($org['status_verifikasi']!=='Terverifikasi'):?><div class="alert warning">Status organisasi: <?=badge($org['status_verifikasi'])?>. Admin perlu memverifikasi organisasi sebelum kegiatan dapat dipublikasikan.</div><?php endif;?></div><div class="stats"><div class="stat"><small>Total kegiatan</small><b><?=$n?></b><span>dibuat organisasi</span></div><div class="stat"><small>Total pendaftar</small><b><?=array_sum(array_column($rows,'pendaftar'))?></b><span>seluruh kegiatan</span></div></div><div class="section-head"><h2>Kegiatan saya</h2><a class="btn btn-primary" href="event_form.php">＋ Buat kegiatan</a></div><div class="table-wrap"><table><tr><th>Nama kegiatan</th><th>Tanggal</th><th>Pendaftar</th><th>Status</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['nama_kegiatan'])?></td><td><?=date('d M Y',strtotime($r['tanggal']))?></td><td><?=$r['pendaftar']?></td><td><?=badge($r['status'])?></td><td><a href="manage_event.php?id=<?=$r['kegiatan_id']?>">Kelola →</a></td></tr><?php endforeach;?></table></div>
<?php }else{
$counts=[];foreach(['users','organizations','events','registrations'] as $t)$counts[$t]=db()->query("SELECT COUNT(*) FROM $t")->fetchColumn();
?><div class="page-heading"><span class="eyebrow">PUSAT KENDALI</span><h1>Dashboard Admin</h1><p class="muted">Kelola pengguna, verifikasi organisasi, dan moderasi kegiatan.</p></div><div class="stats"><?php foreach(['users'=>'Pengguna','organizations'=>'Organisasi','events'=>'Kegiatan','registrations'=>'Pendaftaran'] as $k=>$v):?><div class="stat"><small><?=$v?></small><b><?=$counts[$k]?></b><span>tercatat di sistem</span></div><?php endforeach;?></div><div class="quick-links"><a href="admin.php?tab=org">Verifikasi organisasi →</a><a href="admin.php?tab=events">Moderasi kegiatan →</a><a href="admin.php?tab=users">Kelola pengguna →</a></div><?php } layout_end(); ?>
